import{_ as o,l as i,o as a,c as n,v as r,p as s,x as t,d,i as m,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"承诺与 Merkle 树","description":"","frontmatter":{"title":"承诺与 Merkle 树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/commitment-merkle-tree.md","filePath":"cs/commitment-merkle-tree.md","lastUpdated":1789023840000}'),h={name:"cs/commitment-merkle-tree.md"};function p(k,e,_,E,u,A){const l=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="承诺与-merkle-树" tabindex="-1">承诺与 Merkle 树 <a class="header-anchor" href="#承诺与-merkle-树" aria-label="Permalink to &quot;承诺与 Merkle 树&quot;">​</a></h1><div class="epigraph"><p>承诺先把值藏进盒子：隐藏、绑定，稍后打开。Merkle 树把许多叶子收成一个根，证明某叶子在集合里只需一条路径，不必公开整棵树。</p><footer>—— 据 Pedersen 承诺；Merkle, Protocols for Public Key Cryptosystems, 1980；对照 RFC 6962 对 Merkle 的使用</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/zero-knowledge-intuition">零知识</a>常把承诺当内部消息。缺口是把<strong>承诺</strong>与<strong>集合摘要</strong>钉成工程对象。主干哈希已有；本课不重证碰撞，只讲绑定来自碰撞难、隐藏来自预像或盲随机。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ZK 的第一轮常是承诺。简单 \\(H(x\\|r)\\)：碰撞难则绑定，r 足够则隐藏。Pedersen 在离散对数假设下可加同态，本课点名。Merkle：叶哈希向上，包含证明是 \\(\\log n\\) 个兄弟。缺口是这两件零件，不是 CT 日志的政策（更后）。</p><h3 id="根换了就要重证" tabindex="-1">根换了就要重证 <a class="header-anchor" href="#根换了就要重证" aria-label="Permalink to &quot;根换了就要重证&quot;">​</a></h3><p>叶子一改根变。时间戳只钉某刻的根，不自动更新。</p><p><span class="marginnote">Merkle 1980。证书透明、Git、比特币都用变体；本课不进量化账本。隐藏在哈希承诺里对短 x 要加盐，否则可穷举。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写承诺的两条游戏。画一层 Merkle 路径。指出证明泄漏路径上的兄弟哈希，集合结构部分可见——需要时用更强的零知识集合。</p>',12)),(a(),s(c,null,{default:t(()=>[m(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%80%BC%20x%22%5D%20--%3E%20COM%5B%22%E6%89%BF%E8%AF%BA%20Com(x%2Cr)%22%5D%0A%20%20COM%20--%3E%20OPEN%5B%22%E6%89%93%E5%BC%80%E5%87%BA%E7%A4%BA%20x%2Cr%22%5D%0A%20%20LEAVES%5B%22%E5%8F%B6%E5%AD%90%E5%93%88%E5%B8%8C%22%5D%20--%3E%20ROOT%5B%22Merkle%20%E6%A0%B9%22%5D%0A%20%20PATH%5B%22%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20INC%5B%22%E5%8C%85%E5%90%AB%E8%AF%81%E6%98%8E%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>绑定服务完整性：不能换叶子还声称同一根。隐藏服务保密：未打开前 x 不泄漏（在假设下）。二者与 AEAD 不同：承诺通常不传输「可解密的密文」，只传输可稍后打开的绑定。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把稀疏 Merkle 与 Verkle 写全。秘密共享下一课：把一个秘密拆给多人，与「承诺一个值」正交。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ZK 对话常吃承诺；本课钉隐藏与绑定。</li><li>Merkle 用哈希树做集合包含证明。</li><li>短消息承诺必须加盐，否则穷举破隐藏。</li><li>下一课 Shamir 秘密共享。</li><li>出处：Merkle, 1980；Pedersen；对照 Katz and Lindell 的承诺定义。</li></ul>',8))])}const P=o(h,[["render",p]]);export{B as __pageData,P as default};
